import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow } from '../_helpers/milestone';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

const routes: { url: string; title: RegExp }[] = [
  { url: '/home', title: /^בית · אור הגאולה$/ },
  { url: '/journey', title: /אור הגאולה/ },
  { url: '/journey/history', title: /אור הגאולה/ },
  { url: '/profile', title: /אור הגאולה/ },
  { url: '/zmanim', title: /אור הגאולה/ },
  { url: '/prayers', title: /^תפילות · אור הגאולה$/ },
  { url: '/lessons', title: /^שיעורי תורה · אור הגאולה$/ },
  { url: '/tehilim', title: /אור הגאולה/ },
  { url: '/tehilim/72', title: /^תהילים ע״ב · אור הגאולה$/ },
  { url: '/prayer/mincha_ashkenaz', title: /אור הגאולה/ },
  { url: '/blessings', title: /אור הגאולה/ },
];

test.describe('Web-оболочка — вошедший пользователь', () => {
  test('WS-01 На каждом маршруте user1 document.title не пустой и есть favicon #6a8edf78 @prod-safe @mobile', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. По очереди открыть маршруты; после загрузки прочитать `document.title` и `link[rel*=icon]`.
    for (const r of routes) {
      await test.step(r.url, async () => {
        await page.goto(r.url);
        await expect(page).toHaveTitle(r.title);
        await expect(page).toHaveTitle(/אור הגאולה/);
        const icons = page.locator('link[rel*=icon]');
        expect(await icons.count()).toBeGreaterThan(0);
        for (const href of await icons.evaluateAll((els) => els.map((e) => e.getAttribute('href')))) {
          expect(href).toBe('/favicon.ico');
        }
      });
    }
  });
});
